using GraphApi.Models.SGR.Casas;namespace GraphApi.Services.SGR.Casas{    /// <summary>    /// Define las operaciones de negocio y persistencia para Casas.    /// </summary>    public interface ICasasService    {        /// <summary>        /// Obtiene la lista de Casas con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadCasas>> GetCasas(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Casas con filtros opcionales.        /// </summary>        /// <param name="casaID">Filtro opcional para CasaID.</param>        /// <param name="condominioID">Filtro opcional para CondominioID.</param>        /// <param name="nombreCondominio">Filtro opcional para NombreCondominio.</param>        /// <param name="direccionCondominio">Filtro opcional para DireccionCondominio.</param>        /// <param name="direccionCasa">Filtro opcional para DireccionCasa.</param>        /// <param name="numeroExtCasa">Filtro opcional para NumeroExtCasa.</param>        /// <param name="propietarioUsuarioID">Filtro opcional para PropietarioUsuarioID.</param>        /// <param name="nombrePropietario">Filtro opcional para NombrePropietario.</param>        /// <param name="correoPropietario">Filtro opcional para CorreoPropietario.</param>        /// <param name="fotoUrlPropietario">Filtro opcional para FotoUrlPropietario.</param>        /// <param name="telefonoPropietario">Filtro opcional para TelefonoPropietario.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetCasasDynamic(            int? casaID,            int? condominioID,            string? nombreCondominio,            string? direccionCondominio,            string? direccionCasa,            string? numeroExtCasa,            int? propietarioUsuarioID,            string? nombrePropietario,            string? correoPropietario,            string? fotoUrlPropietario,            string? telefonoPropietario,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Casa.        /// </summary>        /// <param name="objInput">Datos para crear el Casa.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadCasas> CreateCasas(            clCreateCasas objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Casa.        /// </summary>        /// <param name="objInput">Datos para actualizar el Casa, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadCasas?> UpdateCasas(            clUpdateCasas objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Casa por su ID.        /// </summary>        /// <param name="nCasasID">ID del Casa a eliminar.</param>        Task<bool> DeleteCasas(int nCasasID);    }}